<#
    Toolkit - UI / Windows codes

    The Windows codes tab of the Knowledge base. Type an error code in any
    form, an event ID or words; choose a row; read what it means and what to
    try, and for an event the command that reads it on this machine.
#>

# The rows in the list, by title, so a selection finds what it names.
$script:TkReferenceRows = @{}

<#
.SYNOPSIS
    Wires the Windows codes tab.
#>
function Initialize-TkWindowsReference {
    [CmdletBinding()]
    param()

    $search = Get-TkControl -Name 'ReferenceSearch'
    $list   = Get-TkControl -Name 'ReferenceList'

    if (-not $search -or -not $list) {
        return
    }

    $search.Add_TextChanged({
        Update-TkReferenceList -Query (Get-TkControl -Name 'ReferenceSearch').Text
    })

    $list.Add_SelectionChanged({

        $selected = (Get-TkControl -Name 'ReferenceList').SelectedItem

        if ($null -ne $selected) {
            Show-TkReferenceEntry -Title ([string] $selected)
        }
    })

    Show-TkReferenceWelcome
}

<#
.SYNOPSIS
    Fills the list with what matches the search.

.PARAMETER Query
    What was typed.
#>
function Update-TkReferenceList {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [AllowEmptyString()]
        [string] $Query
    )

    $list = Get-TkControl -Name 'ReferenceList'

    if (-not $list) {
        return
    }

    $list.Items.Clear()
    $script:TkReferenceRows = @{}

    if ([string]::IsNullOrWhiteSpace($Query)) {
        Show-TkReferenceWelcome
        return
    }

    foreach ($row in @(Find-TkWindowsReference -Query $Query | Select-Object -First 200)) {
        $script:TkReferenceRows[$row.Title] = $row
        [void] $list.Items.Add($row.Title)
    }

    if ($list.Items.Count -eq 0) {

        $document = New-TkFlowDocument
        Add-TkParagraph -Document $document -Muted -Text 'Nothing in the reference matches. A code can be typed as 0x80070005, 80070005, -2147024891 or 5; an event as its number.'
        Set-TkDocument -ControlName 'ReferenceContent' -Document $document

        return
    }

    # A whole code or an event ID shows its first row at once.
    if ($Query.Trim() -match '^(0[xX])?[0-9A-Fa-f]{8}$|^-\d{6,}$|^\d{1,5}$') {
        $list.SelectedIndex = 0
    }
}

<#
.SYNOPSIS
    Shows what the tab is for, before anything is typed.
#>
function Show-TkReferenceWelcome {
    [CmdletBinding()]
    param()

    $codes  = Import-TkCatalog -Name 'windows-errors'
    $events = Import-TkCatalog -Name 'windows-events'

    $document = New-TkFlowDocument

    Add-TkHeading   -Document $document -Text 'Windows codes' -Level 1
    Add-TkParagraph -Document $document -Text 'Type an error code, an event ID or words in the box. A code can be written the way any tool prints it:'

    Add-TkBulletList -Document $document -Item @(
        '0x80070005 or 80070005, as Windows Update and setup show them',
        '-2147024891, as the update history and many scripts return them',
        '5, a Win32 error number',
        '41 or 4625, an event ID',
        'words such as proxy, component store or locked out'
    )

    Add-TkParagraph -Document $document -Muted -Text (
        '{0} error codes and {1} events, written from Microsoft''s references. A code that is not among them is still decoded into its parts.' -f @($codes.codes).Count, @($events.events).Count
    )

    Set-TkDocument -ControlName 'ReferenceContent' -Document $document
}

<#
.SYNOPSIS
    Shows the row chosen in the list.

.PARAMETER Title
    The title of the row.
#>
function Show-TkReferenceEntry {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [string] $Title
    )

    $row = $script:TkReferenceRows[$Title]

    if (-not $row) {
        return
    }

    if ($row.Kind -eq 'Error code') {
        Show-TkErrorCodeEntry -Info (Get-TkErrorCodeInfo -Code $row.Key)
    }
    else {
        Show-TkEventEntry -Entry $row.Entry
    }
}

<#
.SYNOPSIS
    Shows an error code: its meaning, what to try, and its parts.

.PARAMETER Info
    Output of Get-TkErrorCodeInfo.
#>
function Show-TkErrorCodeEntry {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [pscustomobject] $Info
    )

    $document = New-TkFlowDocument

    Add-TkHeading -Document $document -Text $(if ($Info.Name) { '{0}  {1}' -f $Info.Hex, $Info.Name } else { $Info.Hex }) -Level 1

    if ($Info.Known) {
        Add-TkParagraph -Document $document -Text $Info.Meaning
    }
    else {
        Add-TkParagraph -Document $document -Muted -Text 'This code is not in the reference the toolkit carries, so it gets no name here. What the code itself says is below; search the whole code on Microsoft Learn for the rest.'
    }

    if ($Info.SystemMessage) {
        Add-TkParagraph -Document $document -Text ('Windows message, in the display language: {0}' -f $Info.SystemMessage)
    }

    if ($Info.Action) {
        Add-TkHeading   -Document $document -Text 'What to try' -Level 2
        Add-TkParagraph -Document $document -Text $Info.Action
    }

    $steps = @($Info.Steps | Where-Object { $_ })

    if ($steps.Count -gt 0) {

        $heading = if ($Info.Action) { 'If that is not it: {0}' -f $Info.GroupName.ToLowerInvariant() } else { 'Usual cause: {0}' -f $Info.GroupName.ToLowerInvariant() }

        Add-TkHeading    -Document $document -Text $heading -Level 2
        Add-TkBulletList -Document $document -Item $steps
    }

    Add-TkHeading -Document $document -Text 'The code itself' -Level 2

    $code = [int] ($Info.Value -band 65535)

    $rows = @(
        , @('Kind', [string] $Info.Kind)
        , @('Facility', $(if ($Info.FacilityName) { '{0} ({1})' -f [string] $Info.Facility, $Info.FacilityName } else { [string] $Info.Facility }))
        , @('Code', ('{0} (0x{1:X4})' -f [string] $code, $code))
    )

    if ($null -ne $Info.Win32) {
        $rows += , @('Win32 error', [string] $Info.Win32)
    }

    Add-TkTable -Document $document -Column @('Part', 'Value') -Weight @(1.0, 3.0) -Row $rows

    $catalog = Import-TkCatalog -Name 'windows-errors'

    if ($catalog -and $catalog.references) {
        Add-TkParagraph -Document $document -Muted -Text ('Written from: {0}' -f (@($catalog.references) -join ', '))
    }

    Set-TkDocument -ControlName 'ReferenceContent' -Document $document
}

<#
.SYNOPSIS
    Shows an event: what it means, what to do, and how to read it here.

.PARAMETER Entry
    An event of the catalog.
#>
function Show-TkEventEntry {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        $Entry
    )

    $document = New-TkFlowDocument

    Add-TkHeading -Document $document -Text ('Event {0}, {1}' -f $Entry.id, $Entry.source) -Level 1

    Add-TkSeverityLine -Document $document -Severity ([string] $Entry.severity) -Heading ([string] $Entry.name) `
        -Detail ('{0} log' -f $Entry.log)

    Add-TkParagraph -Document $document -Text ([string] $Entry.meaning)

    if ($Entry.action) {
        Add-TkHeading   -Document $document -Text 'What to do' -Level 2
        Add-TkParagraph -Document $document -Text ([string] $Entry.action)
    }

    Add-TkHeading -Document $document -Text 'Read it on this machine' -Level 2

    if ($Entry.log -eq 'Security') {
        Add-TkParagraph -Document $document -Muted -Text 'The Security log is only readable from an elevated PowerShell.'
    }

    Add-TkCodeBlock -Document $document -Text (Get-TkEventQueryCommand -Entry $Entry)

    $notes = @(
        $(if ($Entry.provider) { 'Provider: {0}.' -f $Entry.provider })
        $(if ($Entry.reference) { 'Source: {0}' -f $Entry.reference })
    ) | Where-Object { $_ }

    if (@($notes).Count -gt 0) {
        Add-TkParagraph -Document $document -Muted -Text ($notes -join ' ')
    }

    Set-TkDocument -ControlName 'ReferenceContent' -Document $document
}


# ==========================================================================
# Source: src/UI/Pages/ToolsPage.ps1
# ==========================================================================

<#
    Toolkit - UI / Tools page, calculators

    The Ports, chmod, Regex, Timestamps and Encoding tabs of the Tools page.
    Each one reads its controls, calls a function of Calculators.ps1 and
    writes plain text, so the result can be selected and copied.
#>

# Set while the chmod controls are written from code, so the handlers that
# follow them do not answer their own change.
$script:TkChmodUpdating = $false

# Set while HTML is loaded into the editor, so the editor does not rewrite
# the HTML box while it is being read from it.
$script:TkEditorLoading = $false

<#
.SYNOPSIS
    Wires the calculator tabs of the Tools page.
#>
function Initialize-TkToolsPage {
    [CmdletBinding()]
    param()

    # --- Chooser ----------------------------------------------------------
    # Found by title in Get-TkToolEntry, like the Diagnostics reports, so a
    # tool inserted in the list cannot shift the others onto the wrong panel.
    $choices = Get-TkControl -Name 'ToolChoices'

    if ($choices) {

        $choices.Add_SelectionChanged({
            $title = Get-TkItemTitle -Item (Get-TkControl -Name 'ToolChoices').SelectedItem

            if ($title) {
                Show-TkTool -Title $title
            }
        })

        [void] (Select-TkListChoice -ListName 'ToolChoices' -Title (@(Get-TkToolEntry)[0].Title))
    }

    # --- Ports ------------------------------------------------------------
    $range = Get-TkControl -Name 'PortRange'

    if ($range) {

        foreach ($name in @(Get-TkPortRangeChoice | ForEach-Object { $_.Label })) {
            [void] $range.Items.Add($name)
        }

        $range.SelectedIndex = 0

        # From and To only count for the custom range.
        $range.Add_SelectionChanged({ Update-TkPortRangeControl })
        Update-TkPortRangeControl
    }

    Register-TkClick -Name 'BtnGeneratePorts' -Action { Invoke-TkPortGeneratorFromUi }
    Register-TkClick -Name 'BtnCopyPorts'     -Action { Copy-TkToolOutput -ControlName 'PortOutput' }

    # --- chmod ------------------------------------------------------------
    foreach ($name in @((Get-TkChmodBitMap).Keys)) {

        $box = Get-TkControl -Name $name

        if ($box) {
            $box.Add_Click({ Update-TkChmodFromCheckBox })
        }
    }

    $octal = Get-TkControl -Name 'ChmodOctal'

    if ($octal) {
        $octal.Add_TextChanged({ Update-TkChmodFromText -Source 'ChmodOctal' })
    }

    $symbolic = Get-TkControl -Name 'ChmodSymbolic'

    if ($symbolic) {
        $symbolic.Add_TextChanged({ Update-TkChmodFromText -Source 'ChmodSymbolic' })
    }

    Register-TkClick -Name 'BtnCopyChmod' -Action { Copy-TkToolOutput -ControlName 'ChmodOutput' }

    Set-TkChmodControl -Bits 493

    # --- Regex ------------------------------------------------------------
    foreach ($name in @('RegexPattern', 'RegexText', 'RegexReplacement')) {

        $box = Get-TkControl -Name $name

        if ($box) {
            $box.Add_TextChanged({ Invoke-TkRegexFromUi })
        }
    }

    foreach ($name in @('RegexIgnoreCase', 'RegexMultiline', 'RegexSingleline')) {

        $box = Get-TkControl -Name $name

        if ($box) {
            $box.Add_Click({ Invoke-TkRegexFromUi })
        }
    }

    Initialize-TkRegexCheatSheet

    # --- Timestamps -------------------------------------------------------
    $timestamp = Get-TkControl -Name 'TimestampInput'

    if ($timestamp) {
        $timestamp.Add_TextChanged({ Update-TkTimestampFromUi })
    }

    Register-TkClick -Name 'BtnTimestampNow' -Action { (Get-TkControl -Name 'TimestampInput').Text = 'now' }

    Update-TkTimestampFromUi

    # --- Encoding ---------------------------------------------------------
    $operation = Get-TkControl -Name 'EncodingOperation'

    if ($operation) {

        foreach ($name in @(Get-TkTextOperationChoice | ForEach-Object { $_.Label })) {
            [void] $operation.Items.Add($name)
        }

        $operation.SelectedIndex = 0
    }

    Register-TkClick -Name 'BtnConvertText' -Action { Invoke-TkTextConversionFromUi }

    Register-TkClick -Name 'BtnSwapText' -Action {
        (Get-TkControl -Name 'EncodingInput').Text = (Get-TkControl -Name 'EncodingOutput').Text
    }

    # The JWT secret verifies live, so a decoded token's verdict updates as the
    # secret is typed without a second click on Convert.
    $jwtSecret = Get-TkControl -Name 'JwtSecret'
    if ($jwtSecret) {
        $jwtSecret.Add_TextChanged({
            if ([string] (Get-TkControl -Name 'EncodingOperation').SelectedItem -eq 'Decode a JWT') {
                Invoke-TkTextConversionFromUi
            }
        })
    }

    # --- UUIDs ------------------------------------------------------------
    $uuidVersion = Get-TkControl -Name 'UuidVersion'

    if ($uuidVersion) {
        [void] $uuidVersion.Items.Add('4, random')
        [void] $uuidVersion.Items.Add('7, ordered by time')
        $uuidVersion.SelectedIndex = 0
    }

    $uuidFormat = Get-TkControl -Name 'UuidFormat'

    if ($uuidFormat) {

        foreach ($choice in @(Get-TkUuidFormatChoice)) {
            [void] $uuidFormat.Items.Add($choice.Label)
        }

        $uuidFormat.SelectedIndex = 0
    }

    # --- Text normalizer --------------------------------------------------
    $normLineEnding = Get-TkControl -Name 'NormalizeLineEnding'
    if ($normLineEnding) {
        foreach ($choice in @('LF (Unix)', 'CRLF (Windows)', 'CR (classic Mac)')) { [void] $normLineEnding.Items.Add($choice) }
        $normLineEnding.SelectedIndex = 0
        $normLineEnding.Add_SelectionChanged({ Update-TkNormalizeFromUi })
    }

    $normTabs = Get-TkControl -Name 'NormalizeTabs'
    if ($normTabs) {
        foreach ($choice in @('Keep tabs', 'Tabs to spaces', 'Spaces to tabs')) { [void] $normTabs.Items.Add($choice) }
        $normTabs.SelectedIndex = 0
        $normTabs.Add_SelectionChanged({ Update-TkNormalizeFromUi })
    }

    $normWidth = Get-TkControl -Name 'NormalizeTabWidth'
    if ($normWidth) {
        foreach ($choice in @('2', '4', '8')) { [void] $normWidth.Items.Add($choice) }
        $normWidth.SelectedIndex = 1
        $normWidth.Add_SelectionChanged({ Update-TkNormalizeFromUi })
    }

    foreach ($checkName in @('NormalizeTrim', 'NormalizeBom')) {
        $check = Get-TkControl -Name $checkName
        if ($check) { $check.Add_Click({ Update-TkNormalizeFromUi }) }
    }

    # --- Indicators of compromise -----------------------------------------
    $iocMode = Get-TkControl -Name 'IocMode'
    if ($iocMode) {
        foreach ($choice in @('Extract indicators', 'Defang text', 'Refang text')) { [void] $iocMode.Items.Add($choice) }
        $iocMode.SelectedIndex = 0
        $iocMode.Add_SelectionChanged({ Update-TkIocFromUi })
    }

    # --- XML --------------------------------------------------------------
    $xmlOperation = Get-TkControl -Name 'XmlOperation'
    if ($xmlOperation) {
        foreach ($choice in @('Format', 'Minify', 'Validate', 'XPath query')) { [void] $xmlOperation.Items.Add($choice) }
        $xmlOperation.SelectedIndex = 0
        $xmlOperation.Add_SelectionChanged({ Update-TkXmlFromUi })
    }

    Register-TkClick -Name 'BtnGenerateUuid' -Action { Invoke-TkUuidFromUi }
    Register-TkClick -Name 'BtnCopyUuid'     -Action { Copy-TkToolOutput -ControlName 'UuidOutput' }
    Register-TkClick -Name 'BtnDecodeUuid'   -Action { Invoke-TkUuidDecodeFromUi }

    # --- Safe Links, URL parser, NATO alphabet, phone numbers -------------
    # Worked out as the text changes: each is a few milliseconds.
    foreach ($binding in @(
        @{ Name = 'SafeLinkInput';    Update = { Update-TkSafeLinkFromUi } }
        @{ Name = 'UrlInput';         Update = { Update-TkUrlFromUi } }
        @{ Name = 'NatoInput';        Update = { Update-TkNatoFromUi } }
        @{ Name = 'PhoneInput';       Update = { Update-TkPhoneFromUi } }
        @{ Name = 'MailHeaderInput';  Update = { Update-TkMailHeaderFromUi } }
        @{ Name = 'CertificateInput'; Update = { Update-TkCertificateFromUi } }
        @{ Name = 'HttpHeaderInput';  Update = { Update-TkHttpHeaderFromUi } }
        @{ Name = 'HiddenCharsInput'; Update = { Update-TkHiddenCharsFromUi } }
        @{ Name = 'ConnectionStringInput'; Update = { Update-TkConnectionStringFromUi } }
        @{ Name = 'TotpInput';        Update = { Update-TkTotpFromUi } }
        @{ Name = 'HashIdInput';      Update = { Update-TkHashIdFromUi } }
        @{ Name = 'UserAgentInput';   Update = { Update-TkUserAgentFromUi } }
        @{ Name = 'NormalizeInput';   Update = { Update-TkNormalizeFromUi } }
        @{ Name = 'IocInput';         Update = { Update-TkIocFromUi } }
        @{ Name = 'XmlInput';         Update = { Update-TkXmlFromUi } }
        @{ Name = 'XmlXPath';         Update = { Update-TkXmlFromUi } }
        @{ Name = 'SidInput';         Update = { Update-TkSidFromUi } }
    )) {
        $box = Get-TkControl -Name $binding.Name

        if ($box) {
            $box.Add_TextChanged($binding.Update)
        }
    }

    # The authenticator code rolls over every window, so a one second timer
    # keeps it and its countdown current while the TOTP tool is open. It
    # refreshes nothing while another tool is shown. A started DispatcherTimer
    # is held alive by the dispatcher, so it needs no field of its own.
    $totpTimer = New-Object System.Windows.Threading.DispatcherTimer
    $totpTimer.Interval = [timespan]::FromSeconds(1)
    $totpTimer.Add_Tick({ Update-TkTotpFromUi })
    $totpTimer.Start()

    # --- Mail records and certificates ------------------------------------
    # The mail check goes out on the network, so it waits for the button, or
    # Enter in the domain box.
    Register-TkClick -Name 'BtnCheckMailDns'    -Action { Invoke-TkMailDnsFromUi }
    Register-TkClick -Name 'BtnOpenCertificate' -Action { Open-TkCertificateFileFromUi }
    Register-TkClick -Name 'BtnCertToPem'       -Action { Convert-TkCertificateFromUi -Format 'Pem' }
    Register-TkClick -Name 'BtnCertToDer'       -Action { Convert-TkCertificateFromUi -Format 'DerBase64' }
    Register-TkClick -Name 'BtnCertPublicKey'   -Action { Convert-TkCertificateFromUi -Format 'PublicKey' }

    $mailDomain = Get-TkControl -Name 'MailDnsDomain'

    if ($mailDomain) {
        $mailDomain.Add_KeyDown({
            param($eventSource, $routedArgs)

            if ($routedArgs.Key -eq [System.Windows.Input.Key]::Return) {
                Invoke-TkMailDnsFromUi
                $routedArgs.Handled = $true
            }
        })
    }

    $markCase = Get-TkControl -Name 'NatoMarkCase'

    if ($markCase) {
        $markCase.Add_Click({ Update-TkNatoFromUi })
    }

    Register-TkClick -Name 'BtnCopySafeLink' -Action {

        $destinations = @(ConvertFrom-TkSafeLink -Text ([string] (Get-TkControl -Name 'SafeLinkInput').Text) | ForEach-Object { $_.Destination })

        if ($destinations.Count -eq 0) {
            Set-TkStatus -Text 'No Safe Links URL to copy from.'
            return
        }

        if (Set-TkClipboard -Text ($destinations -join [Environment]::NewLine)) {
            Set-TkStatus -Text ('{0} destination(s) copied to the clipboard.' -f $destinations.Count)
        }
    }

    $phoneCountry = Get-TkControl -Name 'PhoneCountry'

    if ($phoneCountry) {

        foreach ($country in @(Get-TkPhoneCountry)) {
            [void] $phoneCountry.Items.Add(('{0} (+{1})' -f $country.Name, $country.Code))
        }

        $phoneCountry.SelectedIndex = 0
        $phoneCountry.Add_SelectionChanged({ Update-TkPhoneFromUi })
    }

    # --- Text diff --------------------------------------------------------
    Register-TkClick -Name 'BtnCompareText' -Action { Invoke-TkTextDiffFromUi }

    Register-TkClick -Name 'BtnSwapDiff' -Action {
        $before = Get-TkControl -Name 'DiffBefore'
        $after  = Get-TkControl -Name 'DiffAfter'
        $held         = $before.Text
        $before.Text  = $after.Text
        $after.Text   = $held
    }

    # --- Crontab ----------------------------------------------------------
    $cronPreset = Get-TkControl -Name 'CronPreset'

    if ($cronPreset) {

        foreach ($choice in @(Get-TkCronPreset)) {
            [void] $cronPreset.Items.Add($choice.Label)
        }

        $cronPreset.SelectedIndex = 0

        $cronPreset.Add_SelectionChanged({
            $chosen = @(Get-TkCronPreset) | Where-Object { $_.Label -eq [string] (Get-TkControl -Name 'CronPreset').SelectedItem } | Select-Object -First 1

            if ($chosen -and $chosen.Expression) {
                (Get-TkControl -Name 'CronExpression').Text = $chosen.Expression
            }
        })
    }

    foreach ($name in @('CronExpression', 'CronCommand')) {

        $box = Get-TkControl -Name $name

        if ($box) {
            $box.Add_TextChanged({ Update-TkCronFromUi })
        }
    }

    Register-TkClick -Name 'BtnCopyCron' -Action {
        if (Set-TkClipboard -Text (Get-TkCronLine)) {
            Set-TkStatus -Text 'Crontab line copied to the clipboard.'
        }
    }

    # --- docker run to Compose --------------------------------------------
    Register-TkClick -Name 'BtnConvertDocker' -Action { Invoke-TkDockerComposeFromUi }
    Register-TkClick -Name 'BtnCopyCompose'   -Action { Copy-TkToolOutput -ControlName 'DockerComposeOutput' }

    # --- JSON and YAML ----------------------------------------------------
    $jsonOperation = Get-TkControl -Name 'JsonOperation'

    if ($jsonOperation) {
        foreach ($label in @('Format', 'Minify', 'Validate', 'To YAML', 'To CSV')) {
            [void] $jsonOperation.Items.Add($label)
        }
        $jsonOperation.SelectedIndex = 0
    }

    Register-TkClick -Name 'BtnConvertJson' -Action { Invoke-TkJsonFromUi }
    Register-TkClick -Name 'BtnCopyJson'    -Action { Copy-TkToolOutput -ControlName 'JsonOutput' }

    # --- Number bases -----------------------------------------------------
    $numberBase = Get-TkControl -Name 'NumberBase'

    if ($numberBase) {
        foreach ($label in @('Decimal (10)', 'Hexadecimal (16)', 'Binary (2)', 'Octal (8)')) {
            [void] $numberBase.Items.Add($label)
        }
        $numberBase.SelectedIndex = 0
        $numberBase.Add_SelectionChanged({ Update-TkNumberBaseFromUi })
    }

    $numberInput = Get-TkControl -Name 'NumberInput'
    if ($numberInput) { $numberInput.Add_TextChanged({ Update-TkNumberBaseFromUi }) }

    # --- Data size and transfer time --------------------------------------
    foreach ($name in @('DataSizeInput', 'DataRateInput')) {
        $box = Get-TkControl -Name $name
        if ($box) { $box.Add_TextChanged({ Update-TkDataSizeFromUi }) }
    }

    # --- SDDL -------------------------------------------------------------
    $sddlContext = Get-TkControl -Name 'SddlContext'

    if ($sddlContext) {
        foreach ($label in @('Auto / generic', 'File or folder', 'Registry key', 'Directory object', 'Service')) {
            [void] $sddlContext.Items.Add($label)
        }
        $sddlContext.SelectedIndex = 0
        $sddlContext.Add_SelectionChanged({ Update-TkSddlFromUi })
    }

    $sddlInput = Get-TkControl -Name 'SddlInput'
    if ($sddlInput) { $sddlInput.Add_TextChanged({ Update-TkSddlFromUi }) }

    # --- Active Directory account flags -----------------------------------
    $adFlagAttribute = Get-TkControl -Name 'AdFlagAttribute'

    if ($adFlagAttribute) {
        foreach ($label in @('userAccountControl', 'groupType', 'msDS-SupportedEncryptionTypes')) {
            [void] $adFlagAttribute.Items.Add($label)
        }
        $adFlagAttribute.SelectedIndex = 0
        $adFlagAttribute.Add_SelectionChanged({ Update-TkAdFlagsFromUi })
    }

    $adFlagValue = Get-TkControl -Name 'AdFlagValue'
    if ($adFlagValue) { $adFlagValue.Add_TextChanged({ Update-TkAdFlagsFromUi }) }

    # --- Robocopy ---------------------------------------------------------
    foreach ($name in @('RoboSource', 'RoboDest', 'RoboThreads', 'RoboRetries', 'RoboWait', 'RoboExcludeFiles', 'RoboExcludeDirs', 'RoboLog', 'RoboExitCode')) {
        $box = Get-TkControl -Name $name
        if ($box) { $box.Add_TextChanged({ Update-TkRobocopyFromUi }) }
    }

    foreach ($name in @('RoboMirror', 'RoboEmptyDirs', 'RoboRestartable', 'RoboBackup', 'RoboCopyAll', 'RoboExcludeOlder', 'RoboNoProgress', 'RoboListOnly')) {
        $check = Get-TkControl -Name $name
        if ($check) { $check.Add_Click({ Update-TkRobocopyFromUi }) }
    }

    Register-TkClick -Name 'BtnCopyRobocopy' -Action { Copy-TkToolOutput -ControlName 'RoboOutput' }

    # --- dsacls delegation ------------------------------------------------
    $dsaclsPreset = Get-TkControl -Name 'DsaclsPreset'

    if ($dsaclsPreset) {
        foreach ($preset in @(Get-TkDsaclsPreset)) {
            [void] $dsaclsPreset.Items.Add($preset.Label)
        }
        $dsaclsPreset.SelectedIndex = 0
        $dsaclsPreset.Add_SelectionChanged({ Update-TkDsaclsFromUi })
    }

    $dsaclsObjectType = Get-TkControl -Name 'DsaclsObjectType'

    if ($dsaclsObjectType) {
        foreach ($label in @('user', 'group', 'computer', 'contact', 'organizationalUnit', 'all objects')) {
            [void] $dsaclsObjectType.Items.Add($label)
        }
        $dsaclsObjectType.SelectedIndex = 0
        $dsaclsObjectType.Add_SelectionChanged({ Update-TkDsaclsFromUi })
    }

    $dsaclsInheritance = Get-TkControl -Name 'DsaclsInheritance'

    if ($dsaclsInheritance) {
        foreach ($label in @('This object and all children (/I:T)', 'Child objects only (/I:S)', 'This object and immediate children (/I:P)', 'This object only')) {
            [void] $dsaclsInheritance.Items.Add($label)
        }
        $dsaclsInheritance.SelectedIndex = 0
        $dsaclsInheritance.Add_SelectionChanged({ Update-TkDsaclsFromUi })
    }

    foreach ($name in @('DsaclsObject', 'DsaclsTrustee', 'DsaclsCustom')) {
        $box = Get-TkControl -Name $name
        if ($box) { $box.Add_TextChanged({ Update-TkDsaclsFromUi }) }
    }

    $dsaclsDeny = Get-TkControl -Name 'DsaclsDeny'
    if ($dsaclsDeny) { $dsaclsDeny.Add_Click({ Update-TkDsaclsFromUi }) }

    Register-TkClick -Name 'BtnCopyDsacls' -Action { Copy-TkToolOutput -ControlName 'DsaclsOutput' }

    # --- icacls NTFS permission builder -----------------------------------
    $icaclsAction = Get-TkControl -Name 'IcaclsAction'
    if ($icaclsAction) {
        foreach ($label in @('Grant', 'Deny', 'Remove', 'Reset', 'Set owner', 'Enable inheritance', 'Disable inheritance (copy)', 'Remove inherited', 'Save ACLs to file', 'Restore ACLs from file')) {
            [void] $icaclsAction.Items.Add($label)
        }
        $icaclsAction.SelectedIndex = 0
        $icaclsAction.Add_SelectionChanged({ Update-TkIcaclsFromUi })
    }

    $icaclsInheritance = Get-TkControl -Name 'IcaclsInheritance'
    if ($icaclsInheritance) {
        foreach ($label in @('This folder, subfolders and files', 'This folder only', 'This folder and subfolders', 'This folder and files', 'Subfolders and files only')) {
            [void] $icaclsInheritance.Items.Add($label)
        }
        $icaclsInheritance.SelectedIndex = 0
        $icaclsInheritance.Add_SelectionChanged({ Update-TkIcaclsFromUi })
    }

    foreach ($name in @('IcaclsPath', 'IcaclsTrustee', 'IcaclsFile')) {
        $box = Get-TkControl -Name $name
        if ($box) { $box.Add_TextChanged({ Update-TkIcaclsFromUi }) }
    }

    foreach ($checkName in @('IcaclsRecurse', 'IcaclsContinue', 'IcaclsQuiet', 'IcaclsSymlink',
                             'IcaclsPermFull', 'IcaclsPermModify', 'IcaclsPermRX', 'IcaclsPermRead', 'IcaclsPermWrite', 'IcaclsPermDelete')) {
        $check = Get-TkControl -Name $checkName
        if ($check) { $check.Add_Click({ Update-TkIcaclsFromUi }) }
    }

    Register-TkClick -Name 'BtnCopyIcacls' -Action { Copy-TkToolOutput -ControlName 'IcaclsOutput' }

    # --- Event log query builder ------------------------------------------
    $eventLevel = Get-TkControl -Name 'EventQueryLevel'

    if ($eventLevel) {
        foreach ($choice in @(Get-TkEventLevelChoice)) {
            [void] $eventLevel.Items.Add($choice.Label)
        }
        $eventLevel.SelectedIndex = 0
        $eventLevel.Add_SelectionChanged({ Update-TkEventQueryFromUi })
    }

    $eventPreset = Get-TkControl -Name 'EventQueryPreset'

    if ($eventPreset) {
        foreach ($log in @('System', 'Application', 'Security', 'Setup',
                           'Microsoft-Windows-Windows Defender/Operational',
                           'Microsoft-Windows-TerminalServices-LocalSessionManager/Operational',
                           'Microsoft-Windows-TaskScheduler/Operational',
                           'Microsoft-Windows-PowerShell/Operational')) {
            [void] $eventPreset.Items.Add($log)
        }
        $eventPreset.SelectedIndex = 0
        $eventPreset.Add_SelectionChanged({
            $chosen = [string] (Get-TkControl -Name 'EventQueryPreset').SelectedItem
            if ($chosen) { (Get-TkControl -Name 'EventQueryLog').Text = $chosen }
        })
    }

    foreach ($name in @('EventQueryLog', 'EventQueryIds', 'EventQueryProvider', 'EventQueryHours', 'EventQueryContains', 'EventQueryMax')) {
        $box = Get-TkControl -Name $name
        if ($box) { $box.Add_TextChanged({ Update-TkEventQueryFromUi }) }
    }

    # --- Scheduled task ---------------------------------------------------
    $schtaskSchedule = Get-TkControl -Name 'SchtaskSchedule'

    if ($schtaskSchedule) {
        foreach ($label in @('MINUTE', 'HOURLY', 'DAILY', 'WEEKLY', 'MONTHLY', 'ONCE', 'ONSTART', 'ONLOGON', 'ONIDLE')) {
            [void] $schtaskSchedule.Items.Add($label)
        }
        $schtaskSchedule.SelectedIndex = 2
        $schtaskSchedule.Add_SelectionChanged({ Update-TkSchtaskFromUi })
    }

    foreach ($name in @('SchtaskName', 'SchtaskRun', 'SchtaskModifier', 'SchtaskStartTime', 'SchtaskDay', 'SchtaskRunAs')) {
        $box = Get-TkControl -Name $name
        if ($box) { $box.Add_TextChanged({ Update-TkSchtaskFromUi }) }
    }

    foreach ($name in @('SchtaskHighest', 'SchtaskForce')) {
        $check = Get-TkControl -Name $name
        if ($check) { $check.Add_Click({ Update-TkSchtaskFromUi }) }
    }

    Register-TkClick -Name 'BtnCopySchtask' -Action { Copy-TkToolOutput -ControlName 'SchtaskOutput' }

    # --- HTML editor ------------------------------------------------------
    $editor = Get-TkControl -Name 'HtmlEditor'

    if ($editor) {
        $editor.Document = New-TkEditorDocument -Block @(ConvertFrom-TkHtmlDocument -Html '<h2>Title</h2><p>Write here, with <strong>bold</strong>, <em>italic</em> and <a href="https://learn.microsoft.com/">links</a>.</p><ul><li>A list</li><li>of points</li></ul>')
        $editor.Add_TextChanged({ Update-TkHtmlSourceFromUi })
    }

    Register-TkClick -Name 'BtnEditorBold'      -Action { Invoke-TkEditorCommand -Command 'ToggleBold' }
    Register-TkClick -Name 'BtnEditorItalic'    -Action { Invoke-TkEditorCommand -Command 'ToggleItalic' }
    Register-TkClick -Name 'BtnEditorUnderline' -Action { Invoke-TkEditorCommand -Command 'ToggleUnderline' }
    Register-TkClick -Name 'BtnEditorBullets'   -Action { Invoke-TkEditorCommand -Command 'ToggleBullets' }
    Register-TkClick -Name 'BtnEditorNumbering' -Action { Invoke-TkEditorCommand -Command 'ToggleNumbering' }
    Register-TkClick -Name 'BtnEditorHeading1'  -Action { Set-TkEditorParagraphStyle -Style 'Heading1' }
    Register-TkClick -Name 'BtnEditorHeading2'  -Action { Set-TkEditorParagraphStyle -Style 'Heading2' }
    Register-TkClick -Name 'BtnEditorBody'      -Action { Set-TkEditorParagraphStyle -Style 'Body' }
    Register-TkClick -Name 'BtnEditorLink'      -Action { Set-TkEditorLink }
    Register-TkClick -Name 'BtnHtmlCopy'        -Action { Copy-TkToolOutput -ControlName 'HtmlSource' }
    Register-TkClick -Name 'BtnHtmlLoad'        -Action { Import-TkHtmlIntoEditor }

    Register-TkClick -Name 'BtnEditorClear' -Action {
        (Get-TkControl -Name 'HtmlEditor').Selection.ClearAllProperties()
        Update-TkHtmlSourceFromUi
    }

    Update-TkSafeLinkFromUi
    Update-TkUrlFromUi
    Update-TkNatoFromUi
    Update-TkPhoneFromUi
    # --- QR codes ---------------------------------------------------------
    foreach ($listName in @('QrErrorCorrection')) {

        $levels = Get-TkControl -Name $listName

        if ($levels) {

            foreach ($choice in @(Get-TkQrErrorCorrectionChoice)) {
                [void] $levels.Items.Add($choice.Label)
            }

            $levels.SelectedIndex = 0
            $levels.Add_SelectionChanged({ Update-TkQrFromUi })
        }
    }

    $qrInput = Get-TkControl -Name 'QrInput'

    if ($qrInput) {
        $qrInput.Add_TextChanged({ Update-TkQrFromUi })
    }

    $security = Get-TkControl -Name 'WifiQrSecurity'

    if ($security) {

        foreach ($choice in @(Get-TkWifiQrSecurityChoice)) {
            [void] $security.Items.Add($choice.Label)
        }

        $security.SelectedIndex = 0
        $security.Add_SelectionChanged({ Update-TkWifiQrFromUi })
    }

    $ssid = Get-TkControl -Name 'WifiQrSsid'

    if ($ssid) {
        $ssid.Add_TextChanged({ Update-TkWifiQrFromUi })
    }

    $key = Get-TkControl -Name 'WifiQrPassword'

    if ($key) {
        $key.Add_PasswordChanged({ Update-TkWifiQrFromUi })
    }

    $hidden = Get-TkControl -Name 'WifiQrHidden'

    if ($hidden) {
        $hidden.Add_Click({ Update-TkWifiQrFromUi })
    }

    Register-TkClick -Name 'BtnSaveQr'        -Action { Save-TkQrPicture -ImageName 'QrImage' -FileName 'qr-code' }
    Register-TkClick -Name 'BtnCopyQr'        -Action { Copy-TkQrPicture -ImageName 'QrImage' }
    Register-TkClick -Name 'BtnSaveWifiQr'    -Action { Save-TkQrPicture -ImageName 'WifiQrImage' -FileName ('wifi-{0}' -f ([string] (Get-TkControl -Name 'WifiQrSsid').Text -replace '[^A-Za-z0-9_-]', '-')) }
    Register-TkClick -Name 'BtnCopyWifiQr'    -Action { Copy-TkQrPicture -ImageName 'WifiQrImage' }
    Register-TkClick -Name 'BtnWifiQrCurrent' -Action { Invoke-TkWifiQrCurrentNetwork }

    Update-TkCronFromUi
    Update-TkHtmlSourceFromUi
    Update-TkQrFromUi
    Update-TkWifiQrFromUi
}

# ---------------------------------------------------------------------------
# UUIDs
# ---------------------------------------------------------------------------

<#
.SYNOPSIS
    Generates UUIDs from the choices on the page.
#>
function Invoke-TkUuidFromUi {
    [CmdletBinding()]
    param()

    $output = Get-TkControl -Name 'UuidOutput'
    $count  = 0

    if (-not [int]::TryParse([string] (Get-TkControl -Name 'UuidCount').Text, [ref] $count) -or $count -lt 1 -or $count -gt 1000) {
        $output.Text = 'Type how many, from 1 to 1000.'
        return
    }

    $version = if ((Get-TkControl -Name 'UuidVersion').SelectedIndex -eq 1) { 7 } else { 4 }
    $choice  = @(Get-TkUuidFormatChoice) | Where-Object { $_.Label -eq [string] (Get-TkControl -Name 'UuidFormat').SelectedItem } | Select-Object -First 1
    $format  = if ($choice) { $choice.Format } else { 'Standard' }

    $output.Text = (@(New-TkUuid -Version $version -Count $count) | ForEach-Object { Format-TkUuid -Uuid $_ -Format $format }) -join [Environment]::NewLine
}

<#
.SYNOPSIS
    Decodes the UUID typed on the page.
#>
function Invoke-TkUuidDecodeFromUi {
    [CmdletBinding()]
    param()

    $output = Get-TkControl -Name 'UuidOutput'
    $info   = ConvertFrom-TkUuid -Text ([string] (Get-TkControl -Name 'UuidDecodeInput').Text)

    if (-not $info.Valid) {
        $output.Text = $info.Note
        return
    }

    $lines = New-Object System.Collections.Generic.List[string]

    $lines.Add(('UUID      {0}' -f $info.Uuid))
    $lines.Add(('Kind      {0}' -f $info.VersionName))

    if ($info.Variant) {
        $lines.Add(('Variant   {0}' -f $info.Variant))
    }

    if ($info.Time) {
        $lines.Add(('Created   {0} UTC, {1}' -f $info.Time.ToString('yyyy-MM-dd HH:mm:ss.fff', [Globalization.CultureInfo]::InvariantCulture), (Format-TkRelativeTime -Utc $info.Time)))
    }

    if ($info.Node) {
        $lines.Add(('Node      {0}, {1}' -f $info.Node, (Get-TkMacVendor -MacAddress $info.Node)))
    }

    $lines.Add('')
    $lines.Add($info.Note)

    $output.Text = $lines -join [Environment]::NewLine
}

# ---------------------------------------------------------------------------
# Safe Links and URLs
# ---------------------------------------------------------------------------

<#
.SYNOPSIS
    Decodes the Safe Links pasted on the page, as they are pasted.
#>
function Update-TkSafeLinkFromUi {
    [CmdletBinding()]
    param()

    $output = Get-TkControl -Name 'SafeLinkOutput'
    $box    = Get-TkControl -Name 'SafeLinkInput'

    if (-not $output -or -not $box) {
        return
    }

    $text = [string] $box.Text

    if (-not $text.Trim()) {
        $output.Text = 'Paste a link that starts with https://...safelinks.protection.outlook.com/, or a whole e-mail.'
        return
    }

    $rows = @(ConvertFrom-TkSafeLink -Text $text)

    if ($rows.Count -eq 0) {
        $output.Text = 'No Safe Links URL was found in what was pasted. A link that is not wrapped can be read with the URL parser.'
        return
    }

    $lines  = New-Object System.Collections.Generic.List[string]
    $number = 0

    foreach ($row in $rows) {

        $number++

        $lines.Add(('Link {0}' -f $number))
        $lines.Add(('  Goes to    {0}' -f $row.Destination))
        $lines.Add(('  Site       {0}' -f $row.Host))

        if ($row.Recipient) {
            $lines.Add(('  Sent to    {0}' -f $row.Recipient))
        }

        if ($row.Layers -gt 1) {
            $lines.Add(('  Wrapped    {0} times, as happens when a message is forwarded' -f $row.Layers))
        }

        foreach ($warning in @($row.Warnings)) {
            $lines.Add(('  Warning    {0}' -f $warning))
        }

        $lines.Add('')
    }

    $lines.Add('A Safe Links wrapper means the link is checked when it is clicked, not that the site is genuine: judge the site by its name above.')

    $output.Text = $lines -join [Environment]::NewLine
}

<#
.SYNOPSIS
    Takes apart the link typed on the page, as it is typed.
#>
function Update-TkUrlFromUi {
    [CmdletBinding()]
    param()

    $output = Get-TkControl -Name 'UrlOutput'
    $box    = Get-TkControl -Name 'UrlInput'

    if (-not $output -or -not $box) {
        return
    }

    $part = Get-TkUrlPart -Url ([string] $box.Text)

    if (-not $part.Valid) {
        $output.Text = $part.Note
        return
    }

    $lines = New-Object System.Collections.Generic.List[string]

    $lines.Add(('Scheme      {0}' -f $part.Scheme))

    if ($part.User) {
        $lines.Add(('User        {0}{1}' -f $part.User, $(if ($part.HasPassword) { ', with a password (not shown)' } else { '' })))
    }

    $lines.Add(('Host        {0}' -f $part.UnicodeHost))

    if ($part.AsciiHost -ne $part.UnicodeHost) {
        $lines.Add(('For DNS     {0}' -f $part.AsciiHost))
    }

    $lines.Add(('Host type   {0}' -f $part.HostType))

    if ($part.Port -ge 0) {
        $lines.Add(('Port        {0}{1}' -f $part.Port, $(if ($part.IsDefaultPort) { ', the default for ' + $part.Scheme } else { '' })))
    }

    $lines.Add(('Path        {0}' -f $part.Path))
    $lines.Add(('Origin      {0}' -f $part.Origin))

    if (@($part.Query).Count -gt 0) {

        $lines.Add('')
        $lines.Add(('Query, {0} parameter(s)' -f @($part.Query).Count))

        foreach ($parameter in $part.Query) {
            $lines.Add(('  {0} = {1}' -f $parameter.Name, $(if ($null -eq $parameter.Value) { '(no value)' } else { $parameter.Value })))
        }
    }

    if ($part.Fragment) {
        $lines.Add('')
        $lines.Add(('Fragment    {0}' -f $part.Fragment))
    }

    if (@($part.Warnings).Count -gt 0) {

        $lines.Add('')

        foreach ($warning in $part.Warnings) {
            $lines.Add(('Warning     {0}' -f $warning))
        }
    }

    if ($part.Note) {
        $lines.Add('')
        $lines.Add($part.Note)
    }

    $output.Text = $lines -join [Environment]::NewLine
}

