        $output.Text = (Format-TkAdFlags -Report $report) -join [Environment]::NewLine
    }
    catch {
        $output.Text = $_.Exception.Message
    }
}

<#
.SYNOPSIS
    Builds the robocopy command from the controls, and reads an exit code.
#>
function Update-TkRobocopyFromUi {
    [CmdletBinding()]
    param()

    $output = Get-TkControl -Name 'RoboOutput'

    if (-not $output) {
        return
    }

    $source = [string] (Get-TkControl -Name 'RoboSource').Text
    $dest   = [string] (Get-TkControl -Name 'RoboDest').Text

    $lines = New-Object System.Collections.Generic.List[string]

    if ($source.Trim() -and $dest.Trim()) {

        $intOr = {
            param($name)
            $raw = ([string] (Get-TkControl -Name $name).Text).Trim()
            if ($raw -match '^\d+$') { [int] $raw } else { $null }
        }

        $options = @{
            Mirror         = [bool] (Get-TkControl -Name 'RoboMirror').IsChecked
            EmptyDirectories = [bool] (Get-TkControl -Name 'RoboEmptyDirs').IsChecked
            Restartable    = [bool] (Get-TkControl -Name 'RoboRestartable').IsChecked
            Backup         = [bool] (Get-TkControl -Name 'RoboBackup').IsChecked
            CopyAll        = [bool] (Get-TkControl -Name 'RoboCopyAll').IsChecked
            ExcludeOlder   = [bool] (Get-TkControl -Name 'RoboExcludeOlder').IsChecked
            NoProgress     = [bool] (Get-TkControl -Name 'RoboNoProgress').IsChecked
            ListOnly       = [bool] (Get-TkControl -Name 'RoboListOnly').IsChecked
            ExcludeFiles   = @(([string] (Get-TkControl -Name 'RoboExcludeFiles').Text) -split ',' | ForEach-Object { $_.Trim() } | Where-Object { $_ })
            ExcludeDirs    = @(([string] (Get-TkControl -Name 'RoboExcludeDirs').Text) -split ',' | ForEach-Object { $_.Trim() } | Where-Object { $_ })
            Log            = ([string] (Get-TkControl -Name 'RoboLog').Text).Trim()
        }

        $threads = & $intOr 'RoboThreads'
        $retries = & $intOr 'RoboRetries'
        $wait    = & $intOr 'RoboWait'
        if ($null -ne $threads) { $options.Threads = $threads }
        if ($null -ne $retries) { $options.Retries = $retries }
        if ($null -ne $wait)    { $options.Wait    = $wait }

        $lines.Add((Build-TkRobocopyCommand -Source $source -Destination $dest -Options $options))
    }
    else {
        $lines.Add('Type a source and a destination.')
    }

    $exitText = ([string] (Get-TkControl -Name 'RoboExitCode').Text).Trim()

    if ($exitText -match '^\d+$') {
        $decoded = ConvertFrom-TkRobocopyExitCode -Code ([int] $exitText)
        $lines.Add('')
        $lines.Add(('Exit code {0}: {1}' -f $decoded.Code, $(if ($decoded.Success) { 'success' } else { 'at least one failure' })))
        foreach ($meaning in $decoded.Meanings) {
            $lines.Add(('  - {0}' -f $meaning))
        }
    }

    $output.Text = $lines -join [Environment]::NewLine
}

<#
.SYNOPSIS
    Builds the schtasks command from the controls, as they change.
#>
function Update-TkSchtaskFromUi {
    [CmdletBinding()]
    param()

    $output = Get-TkControl -Name 'SchtaskOutput'

    if (-not $output) {
        return
    }

    $name = [string] (Get-TkControl -Name 'SchtaskName').Text
    $run  = [string] (Get-TkControl -Name 'SchtaskRun').Text

    if (-not $name.Trim() -or -not $run.Trim()) {
        $output.Text = 'Type a task name and a program to run.'
        return
    }

    $schedule = [string] (Get-TkControl -Name 'SchtaskSchedule').SelectedItem
    if (-not $schedule) { $schedule = 'DAILY' }

    $options = @{
        Modifier          = [string] (Get-TkControl -Name 'SchtaskModifier').Text
        StartTime         = [string] (Get-TkControl -Name 'SchtaskStartTime').Text
        Day               = [string] (Get-TkControl -Name 'SchtaskDay').Text
        RunAs             = [string] (Get-TkControl -Name 'SchtaskRunAs').Text
        HighestPrivileges = [bool] (Get-TkControl -Name 'SchtaskHighest').IsChecked
        Force             = [bool] (Get-TkControl -Name 'SchtaskForce').IsChecked
    }

    try {
        $output.Text = Build-TkSchtasksCommand -Name $name -Run $run -Schedule $schedule -Options $options
    }
    catch {
        $output.Text = $_.Exception.Message
    }
}

<#
.SYNOPSIS
    Builds the dsacls delegation command from the controls, as they change.
#>
function Update-TkDsaclsFromUi {
    [CmdletBinding()]
    param()

    $output = Get-TkControl -Name 'DsaclsOutput'

    if (-not $output) {
        return
    }

    $object  = [string] (Get-TkControl -Name 'DsaclsObject').Text
    $trustee = [string] (Get-TkControl -Name 'DsaclsTrustee').Text

    if (-not $object.Trim() -or -not $trustee.Trim()) {
        $output.Text = 'Type the OU distinguished name and who to delegate to.'
        return
    }

    $preset = @(Get-TkDsaclsPreset) | Where-Object { $_.Label -eq [string] (Get-TkControl -Name 'DsaclsPreset').SelectedItem } | Select-Object -First 1
    if (-not $preset) { $preset = @(Get-TkDsaclsPreset)[0] }

    $typeLabel = [string] (Get-TkControl -Name 'DsaclsObjectType').SelectedItem
    $type      = if ($typeLabel -and $typeLabel -ne 'all objects') { $typeLabel } else { '' }

    $inheritance = switch ([string] (Get-TkControl -Name 'DsaclsInheritance').SelectedItem) {
        'Child objects only (/I:S)'                       { 'S' }
        'This object and immediate children (/I:P)'       { 'P' }
        'This object only'                                { '' }
        default                                           { 'T' }
    }

    if ($preset.Label -eq 'Custom') {
        $rights = ([string] (Get-TkControl -Name 'DsaclsCustom').Text).Trim()
        if (-not $rights) {
            $output.Text = 'Type the dsacls rights for the Custom task, such as CCDC;computer or WPRP;member;group.'
            return
        }
    }
    else {
        $rights = & $preset.Build $type
    }

    try {
        $command = Build-TkDsaclsCommand -ObjectDn $object -Trustee $trustee -Rights $rights -Inheritance $inheritance -Deny:([bool] (Get-TkControl -Name 'DsaclsDeny').IsChecked)
        $output.Text = @($command, '', $preset.Description, 'Run elevated on a domain-joined machine with the AD tools. dsacls reads the current ACL when run with no /G or /D.') -join [Environment]::NewLine
    }
    catch {
        $output.Text = $_.Exception.Message
    }
}

<#
.SYNOPSIS
    Builds the icacls command from the fields on the page, as they change.
#>
function Update-TkIcaclsFromUi {
    [CmdletBinding()]
    param()

    $output = Get-TkControl -Name 'IcaclsOutput'

    if (-not $output) {
        return
    }

    $actionLabel = [string] (Get-TkControl -Name 'IcaclsAction').SelectedItem
    $action = switch ($actionLabel) {
        'Deny'                       { 'Deny' }
        'Remove'                     { 'Remove' }
        'Reset'                      { 'Reset' }
        'Set owner'                  { 'SetOwner' }
        'Enable inheritance'         { 'InheritEnable' }
        'Disable inheritance (copy)' { 'InheritDisable' }
        'Remove inherited'           { 'InheritRemove' }
        'Save ACLs to file'          { 'Save' }
        'Restore ACLs from file'     { 'Restore' }
        default                      { 'Grant' }
    }

    $needsTrustee    = $action -in @('Grant', 'Deny', 'Remove', 'SetOwner')
    $needsPermission = $action -in @('Grant', 'Deny')
    $needsFile       = $action -in @('Save', 'Restore')

    # Show only the fields the action uses, and rename the trustee for SetOwner.
    Set-TkControlVisible -Name 'IcaclsPermissionRow' -Visible $needsPermission
    Set-TkControlVisible -Name 'IcaclsTrustee'       -Visible $needsTrustee
    Set-TkControlVisible -Name 'IcaclsTrusteeLabel'  -Visible $needsTrustee
    Set-TkControlVisible -Name 'IcaclsFile'          -Visible $needsFile
    Set-TkControlVisible -Name 'IcaclsFileLabel'     -Visible $needsFile

    $trusteeLabel = Get-TkControl -Name 'IcaclsTrusteeLabel'
    if ($trusteeLabel) { $trusteeLabel.Text = if ($action -eq 'SetOwner') { 'Owner' } else { 'Trustee' } }

    # The permission hierarchy: a higher right greys out the ones it includes.
    $full   = [bool] (Get-TkControl -Name 'IcaclsPermFull').IsChecked
    $modify = [bool] (Get-TkControl -Name 'IcaclsPermModify').IsChecked
    $rx     = [bool] (Get-TkControl -Name 'IcaclsPermRX').IsChecked

    (Get-TkControl -Name 'IcaclsPermModify').IsEnabled = -not $full
    (Get-TkControl -Name 'IcaclsPermRX').IsEnabled     = -not ($full -or $modify)
    (Get-TkControl -Name 'IcaclsPermRead').IsEnabled   = -not ($full -or $modify -or $rx)
    (Get-TkControl -Name 'IcaclsPermWrite').IsEnabled  = -not ($full -or $modify)
    (Get-TkControl -Name 'IcaclsPermDelete').IsEnabled = -not ($full -or $modify)

    $path = [string] (Get-TkControl -Name 'IcaclsPath').Text
    if (-not $path.Trim()) {
        $output.Text = 'Type the path of the file or folder.'
        return
    }

    if ($needsTrustee -and -not ([string] (Get-TkControl -Name 'IcaclsTrustee').Text).Trim()) {
        $output.Text = if ($action -eq 'SetOwner') { 'Type the owner: DOMAIN\User, a UPN or a SID.' } else { 'Type the trustee: DOMAIN\User, a UPN or a SID.' }
        return
    }

    if ($needsFile -and -not ([string] (Get-TkControl -Name 'IcaclsFile').Text).Trim()) {
        $output.Text = 'Type the path of the ACL file.'
        return
    }

    $permission = ''
    if ($needsPermission) {

        $selected = New-Object System.Collections.Generic.List[string]
        foreach ($pair in @(
            @{ Name = 'IcaclsPermFull';   Label = 'Full control' },
            @{ Name = 'IcaclsPermModify'; Label = 'Modify' },
            @{ Name = 'IcaclsPermRX';     Label = 'Read & execute' },
            @{ Name = 'IcaclsPermRead';   Label = 'Read' },
            @{ Name = 'IcaclsPermWrite';  Label = 'Write' },
            @{ Name = 'IcaclsPermDelete'; Label = 'Delete' }
        )) {
            if ([bool] (Get-TkControl -Name $pair.Name).IsChecked) { $selected.Add($pair.Label) }
        }

        $permission = Resolve-TkIcaclsPermission -Selected $selected.ToArray()

        if (-not $permission) {
            $output.Text = 'Tick at least one permission to grant or deny.'
            return
        }
    }

    $inheritance = if ($needsPermission) {
        switch ([string] (Get-TkControl -Name 'IcaclsInheritance').SelectedItem) {
            'This folder only'           { '' }
            'This folder and subfolders' { '(CI)' }
            'This folder and files'      { '(OI)' }
            'Subfolders and files only'  { '(OI)(CI)(IO)' }
            default                      { '(OI)(CI)' }
        }
    }
    else { '' }

    $command = Build-TkIcaclsCommand -Path $path -Action $action `
        -Trustee ([string] (Get-TkControl -Name 'IcaclsTrustee').Text) `
        -Permission $permission -Inheritance $inheritance `
        -File ([string] (Get-TkControl -Name 'IcaclsFile').Text) `
        -Recurse:([bool] (Get-TkControl -Name 'IcaclsRecurse').IsChecked) `
        -ContinueOnError:([bool] (Get-TkControl -Name 'IcaclsContinue').IsChecked) `
        -Quiet:([bool] (Get-TkControl -Name 'IcaclsQuiet').IsChecked) `
        -Symlink:([bool] (Get-TkControl -Name 'IcaclsSymlink').IsChecked)

    $output.Text = @($command, '', 'icacls edits the NTFS access control list. Run it elevated. Read the current permissions with icacls "path" and no options.') -join [Environment]::NewLine
}

<#
.SYNOPSIS
    Grades the HTTP response headers pasted on the page, as they are pasted.
#>
function Update-TkHttpHeaderFromUi {
    [CmdletBinding()]
    param()

    $output = Get-TkControl -Name 'HttpHeaderOutput'
    $box    = Get-TkControl -Name 'HttpHeaderInput'

    if (-not $output -or -not $box) {
        return
    }

    $text = [string] $box.Text

    if (-not $text.Trim()) {
        $output.Text = 'Paste a site''s response headers. In the browser dev tools: Network, click the request, Headers, Response headers. Or run curl -I https://the-site.'
        return
    }

    $report = Get-TkHttpHeaderReport -Text $text

    if (@($report.Headers).Count -eq 0) {
        $output.Text = 'No header was recognised. Headers are lines such as Strict-Transport-Security: max-age=... , pasted as the tools show them.'
        return
    }

    $output.Text = (Format-TkHttpHeaderReport -Report $report) -join [Environment]::NewLine
}

